content.content:
  1	// Sidebar contents in the two layouts the shell uses (Grok Bot style): the expanded panel
  2	// (featured orchestrator tile + "Specialists" rows) and the compact avatar rail.
  3	// Row markup started from rakazo's bots sidebar (apps/web/src/pages/Shell.tsx ~2811-3263),
  4	// Apache-2.0, github.com/elie222/rakazo@912c977.
  5	import type { UIMessage } from "ai";
  6	import { Moon, PanelLeftClose, PanelLeftOpen, Plus, Search, Sun, X } from "lucide-react";
  7	import { AnimatePresence, type Transition, type Variants } from "motion/react";
  8	import * as m from "motion/react-m";
  9	import { createContext, type ReactNode, useContext, useEffect, useState } from "react";
 10	import { BotAvatar } from "@/components/avatar/bot-avatar";
 11	import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group";
 12	import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
 13	import type { AgentRowState } from "@/hooks/useAgentChat";
 14	import type { AgentSummary } from "@/hooks/useAgents";
 15	import { agentAvatarValue } from "@/lib/agent-avatar";
 16	import { type ResolvedAppearance, setUiAppearance } from "@/lib/appearance";
 17	import { messageTime } from "@/lib/chats";
 18	import { messageText } from "@/lib/message-parts";
 19	import { DURATION, enterTransition, exitTransition, fade, pop, SPRING, STAGGER, STAGGER_CAP } from "@/lib/motion";
 20	import { agentMatches, groupAgents, PRIMARY_AGENT_KEY } from "@/lib/sidebar";
 21	
 22	export type SidebarSearch = {
 23	  query: string;
 24	  setQuery: (query: string) => void;
 25	  open: boolean;
 26	  setOpen: (open: boolean) => void;
 27	};
 28	
 29	export type SidebarPanelProps = {
 30	  agents: AgentSummary[];
 31	  rows: Record<string, AgentRowState>;
 32	  activeKey: string | null;
 33	  onSelect: (key: string) => void;
 34	  onNewChat: () => void;
 35	  search: SidebarSearch;
 36	  /** Switch between expanded and rail (absent on the mobile overlay). */
 37	  onToggleCompact?: () => void;
 38	};
 39	
 40	/**
 41	 * Rail ↔ expanded morph state, provided by the docked sidebar (the mobile overlay uses the
 42	 * default: always idle). `chrome` = labels visible; `travel` = the transition shared avatars
 43	 * use while they fly between layouts.
 44	 *   phase 1: chrome off (labels fade out) → phase 2: layouts flip, avatars + width travel
 45	 *   → phase 3: chrome on (labels fade in). Collapse is the same sequence in reverse.
 46	 */
 47	export type SidebarMorph = {
 48	  chrome: boolean;
 49	  travel: Transition | undefined;
 50	  /** Called when a shared avatar's layout animation starts, to start the width in sync. */
 51	  onTravelStart?: () => void;
 52	};
 53	export const SidebarMorphContext = createContext<SidebarMorph>({ chrome: true, travel: undefined });
 54	const useMorph = () => useContext(SidebarMorphContext);
 55	
 56	/**
 57	 * Anything that isn't a shared avatar: fades out before the layouts flip and back in after
 58	 * the avatars land. Driven by state (initial={false}), so a layout that mounts mid-morph
 59	 * starts hidden and waits for phase 3.
 60	 */
 61	function Label({ children, className, inline = false }: { children: ReactNode; className?: string; inline?: boolean }) {
 62	  const { chrome } = useMorph();
 63	  const props = {
 64	    "data-morph-label": "",
 65	    variants: fade,
 66	    initial: false as const,
 67	    animate: chrome ? "visible" : "hidden",
 68	    className,
 69	  };
 70	  return inline ? <m.span {...props}>{children}</m.span> : <m.div {...props}>{children}</m.div>;
 71	}
 72	
 73	/** Items rise in one after another; a filtered-out row leaves the way it came. */
 74	const itemVariants: Variants = {
 75	  hidden: { opacity: 0, y: 6, transition: exitTransition(DURATION.base) },
 76	  visible: (index: number = 0) => ({
 77	    opacity: 1,
 78	    y: 0,
 79	    transition: enterTransition(DURATION.base, Math.min(index, STAGGER_CAP) * STAGGER),
 80	  }),
 81	};
 82	
 83	// The roster staggers in once per page load, not every time a panel remounts
 84	// (expand/collapse, reopening the mobile overlay).
 85	let rosterStaggered = false;
 86	function useFirstLoadStagger(): boolean {
 87	  const [stagger] = useState(() => !rosterStaggered);
 88	  useEffect(() => {
 89	    rosterStaggered = true;
 90	  }, []);
 91	  return stagger;
 92	}
 93	
 94	type Badge = "working" | "error" | "unread" | null;
 95	const badgeFor = (row: AgentRowState | undefined): Badge =>
 96	  row?.running ? "working" : row?.error ? "error" : row?.unread ? "unread" : null;
 97	
 98	/**
 99	 * Avatar with a corner badge: pulsing while working, red on failure, a dot when unread.
100	 * Specialist rows pass `activityOnly` because they show unread as an inline dot instead.
101	 */
102	function AgentAvatar({
103	  agent,
104	  size,
105	  row,
106	  activityOnly = false,
107	}: {
108	  agent: AgentSummary;
109	  size: number;
110	  row?: AgentRowState;
111	  activityOnly?: boolean;
112	}) {
113	  const { chrome, travel, onTravelStart } = useMorph();
114	  const status = badgeFor(row);
115	  const badge = activityOnly && status === "unread" ? null : status;
116	  return (
117	    // Shared across layouts: the same agent's avatar flies (and scales 40↔56/36) between the
118	    // rail and the expanded panel instead of disappearing in one and appearing in the other.
119	    <m.span
120	      layoutId={`sidebar-avatar-${agent.key}`}
121	      transition={chrome ? undefined : travel}
122	      onLayoutAnimationStart={chrome ? undefined : onTravelStart}
123	      data-morph-avatar={agent.key}
124	      className="relative inline-flex shrink-0"
125	    >
126	      <BotAvatar
127	        color={agentAvatarValue(agent.id)}
128	        identity={agent.id}
129	        size={size}
130	        status={row?.running ? "running" : undefined}
131	      />
132	      <AnimatePresence initial={false}>
133	        {badge ? (
134	          <m.span
135	            key={badge}
136	            data-testid={`badge-${badge}`}
137	            aria-hidden="true"
138	            variants={pop}
139	            initial="hidden"
140	            animate="visible"
141	            exit="hidden"
142	            className="absolute -end-0.5 -top-0.5 grid h-3 w-3 place-items-center rounded-full bg-sidebar"
143	          >
144	            <span
145	              className={`h-2 w-2 rounded-full ${
146	                badge === "working" ? "bg-warning" : badge === "error" ? "bg-destructive" : "bg-foreground"
147	              }`}
148	              style={badge === "working" ? { animation: "rkPulse 1.2s ease-in-out infinite" } : undefined}
149	            />
150	          </m.span>
151	        ) : null}
152	      </AnimatePresence>
153	    </m.span>
154	  );
155	}
156	
157	/**
158	 * The one selection highlight, shared by the rail square, the featured tile and the rows:
159	 * it springs between agents within a layout and travels with the morph between layouts.
160	 * Radius lives in `style` (14/16/12) so Motion corrects the corners while it stretches.
161	 */
162	function SelectedHighlight({ radius }: { radius: number }) {
163	  const { chrome, travel } = useMorph();
164	  return (
165	    <m.span
166	      layoutId="sidebar-selected"
167	      data-morph-highlight=""
168	      transition={chrome ? SPRING : travel}
169	      aria-hidden="true"
170	      className="absolute inset-0 z-0 bg-sidebar-accent"
171	      style={{ borderRadius: radius }}
172	    />
173	  );
174	}
175	
176	const iconButton =
177	  "grid h-8 w-8 shrink-0 place-items-center rounded-lg text-muted-foreground/80 transition-colors duration-(--motion-fast) ease-(--ease-standard) hover:bg-sidebar-accent hover:text-foreground";
178	
179	/** Expanded layout: wordmark + search/new chat, featured tile, specialists, theme toggle. */
180	export function ExpandedPanel({ agents, rows, activeKey, onSelect, onNewChat, search, onToggleCompact }: SidebarPanelProps) {
181	  const stagger = useFirstLoadStagger();
182	  const matches = (agent: AgentSummary) => agentMatches(agent, search.query);
183	  const { primary, specialists } = groupAgents(agents);
184	  const shownPrimary = primary.filter(matches);
185	  const shownSpecialists = specialists.filter(matches);
186	  const closeSearch = () => {
187	    search.setQuery("");
188	    search.setOpen(false);
189	  };
190	
191	  return (
192	    <div className="flex h-full min-h-0 flex-col">
193	      <Label className="flex h-[52px] shrink-0 items-center gap-1 px-3 pt-2">
194	        <AnimatePresence mode="wait" initial={false}>
195	          {search.open ? (
196	            <m.div key="search" variants={fade} initial="hidden" animate="visible" exit="hidden" className="min-w-0 flex-1">
197	              <InputGroup className="h-8 rounded-lg border border-border bg-card text-muted-foreground focus-within:border-ring dark:bg-input">
198	                <InputGroupAddon>
199	                  <Search size={14} strokeWidth={1.8} aria-hidden="true" />
200	                </InputGroupAddon>
201	                <InputGroupInput
202	                  autoFocus
203	                  value={search.query}
204	                  onChange={(event) => search.setQuery(event.target.value)}
205	                  onKeyDown={(event) => {
206	                    if (event.key === "Escape") closeSearch();
207	                  }}
208	                  onBlur={() => {
209	                    if (!search.query.trim()) closeSearch();
210	                  }}
211	                  placeholder="Search agents"
212	                  aria-label="Search agents"
213	                  autoComplete="off"
214	                  name="sidebar-search"
215	                />
216	                <InputGroupAddon align="inline-end">
217	                  <button
218	                    type="button"
219	                    aria-label="Close search"
220	                    onMouseDown={(event) => event.preventDefault()}
221	                    onClick={closeSearch}
222	                    className="grid h-5 w-5 place-items-center rounded text-muted-foreground hover:text-foreground"
223	                  >
224	                    <X size={13} strokeWidth={1.8} />
225	                  </button>
226	                </InputGroupAddon>
227	              </InputGroup>
228	            </m.div>
229	          ) : (
230	            <m.span
231	              key="wordmark"
232	              variants={fade}
233	              initial="hidden"
234	              animate="visible"
235	              exit="hidden"
236	              className="min-w-0 flex-1 truncate ps-1.5 text-[15px] font-semibold tracking-tight text-foreground"
237	            >
238	              nlhack
239	            </m.span>
240	          )}
241	        </AnimatePresence>
242	        {search.open ? null : (
243	          <button type="button" aria-label="Search agents" title="Search" onClick={() => search.setOpen(true)} className={iconButton}>
244	            <Search size={16} strokeWidth={1.8} aria-hidden="true" />
245	          </button>
246	        )}
247	        <button type="button" aria-label="New chat" title="New chat" onClick={onNewChat} className={iconButton}>
248	          <Plus size={17} strokeWidth={1.8} aria-hidden="true" />
249	        </button>
250	        {onToggleCompact ? (
251	          <button
252	            type="button"
253	            aria-label="Collapse sidebar"
254	            title="Collapse sidebar"
255	            onClick={onToggleCompact}
256	            className={iconButton}
257	          >
258	            <PanelLeftClose size={16} strokeWidth={1.8} aria-hidden="true" />
259	          </button>
260	        ) : null}
261	      </Label>
262	
263	      <nav aria-label="Agents" className="rk-scroll relative min-h-0 flex-1 overflow-y-auto overflow-x-hidden px-2.5 pb-3 pt-1">
264	        <AnimatePresence initial={stagger}>
265	          {shownPrimary.length > 0 ? (
266	            <m.div key="featured" layout="position" className="flex flex-wrap justify-center gap-2 px-0.5 pb-3 pt-1">
267	              {shownPrimary.map((agent, index) => {
268	                const selected = agent.key === activeKey;
269	                return (
270	                  <m.button
271	                    key={agent.key}
272	                    type="button"
273	                    data-testid="featured-agent"
274	                    custom={index}
275	                    variants={itemVariants}
276	                    initial="hidden"
277	                    animate="visible"
278	                    exit="hidden"
279	                    aria-current={selected ? "page" : undefined}
280	                    onClick={() => onSelect(agent.key)}
281	                    className={`relative flex w-24 flex-col items-center gap-2 rounded-2xl px-2 pb-2.5 pt-3 transition-colors duration-(--motion-fast) ease-(--ease-standard) ${
282	                      selected ? "" : "hover:bg-sidebar-accent/60"
283	                    }`}
284	                  >
285	                    {selected ? <SelectedHighlight radius={16} /> : null}
286	                    <AgentAvatar agent={agent} size={56} row={rows[agent.key]} />
287	                    <Label inline className="relative w-full truncate text-center text-[13px] font-medium text-foreground">
288	                      {agent.name}
289	                    </Label>
290	                  </m.button>
291	                );
292	              })}
293	            </m.div>
294	          ) : null}
295	          {shownSpecialists.length > 0 ? (
296	            <m.p
297	              key="specialists-label"
298	              layout="position"
299	              variants={fade}
300	              initial="hidden"
301	              animate="visible"
302	              exit="hidden"
303	              className="px-2.5 pb-1.5 pt-1 text-[12px] font-medium text-muted-foreground/70"
304	            >
305	              <Label inline>Specialists</Label>
306	            </m.p>
307	          ) : null}
308	          {shownSpecialists.map((agent, index) => (
309	            <SpecialistRow
310	              key={agent.key}
311	              agent={agent}
312	              index={index + shownPrimary.length}
313	              row={rows[agent.key]}
314	              selected={agent.key === activeKey}
315	              onSelect={onSelect}
316	            />
317	          ))}
318	          {shownPrimary.length + shownSpecialists.length === 0 ? (
319	            <m.p
320	              key="no-match"
321	              variants={fade}
322	              initial="hidden"
323	              animate="visible"
324	              exit="hidden"
325	              className="px-2.5 py-6 text-center text-[13px] text-muted-foreground"
326	            >
327	              <Label inline>No agents match “{search.query}”.</Label>
328	            </m.p>
329	          ) : null}
330	        </AnimatePresence>
331	      </nav>
332	
333	      <Label className="flex shrink-0 flex-col">
334	        <ThemeToggle />
335	      </Label>
336	    </div>
337	  );
338	}
339	
340	function SpecialistRow({
341	  agent,
342	  index,
343	  row,
344	  selected,
345	  onSelect,
346	}: {
347	  agent: AgentSummary;
348	  index: number;
349	  row?: AgentRowState;
350	  selected: boolean;
351	  onSelect: (key: string) => void;
352	}) {
353	  const last = row?.messages.at(-1);
354	  const lastTime = last ? messageTime(last.id) : undefined;
355	  const status = row?.running ? "working" : row?.error ? "error" : "idle";
356	  // One line: the latest message, or the run state. Nothing before the first message.
357	  const preview = status === "working" ? "Working…" : status === "error" ? "Reply failed" : last ? previewText(last) : "";
358	  return (
359	    <m.button
360	      type="button"
361	      data-testid="specialist-row"
362	      layout="position"
363	      custom={index}
364	      variants={itemVariants}
365	      initial="hidden"
366	      animate="visible"
367	      exit="hidden"
368	      aria-current={selected ? "page" : undefined}
369	      onClick={() => onSelect(agent.key)}
370	      className="relative flex w-full items-center gap-3 rounded-xl px-2.5 py-2 text-start transition-colors duration-(--motion-fast) ease-(--ease-standard) hover:bg-sidebar-accent/60"
371	    >
372	      {/* Under the other rows' content too (z-0 vs z-[1]) while it slides between rows. */}
373	      {selected ? <SelectedHighlight radius={12} /> : null}
374	      <span className="relative z-[1]">
375	        <AgentAvatar agent={agent} size={36} row={row} activityOnly />
376	      </span>
377	      <Label inline className="relative z-[1] flex min-w-0 flex-1 flex-col">
378	        <span className="flex items-center justify-between gap-1.5">
379	          <span
380	            dir="auto"
381	            className={`min-w-0 truncate text-[14px] text-foreground ${row?.unread ? "font-semibold" : "font-medium"}`}
382	          >
383	            {agent.name}
384	            {row?.unread ? <span className="sr-only"> (unread)</span> : null}
385	          </span>
386	          <span className="flex shrink-0 items-center gap-1.5">
387	            {lastTime !== undefined ? (
388	              <span className="text-[11.5px] tabular-nums text-muted-foreground/60">{formatRosterTime(lastTime)}</span>
389	            ) : null}
390	            <AnimatePresence initial={false}>
391	              {row?.unread ? (
392	                <m.span
393	                  key="unread"
394	                  data-testid="unread-dot"
395	                  aria-hidden="true"
396	                  variants={pop}
397	                  initial="hidden"
398	                  animate="visible"
399	                  exit="hidden"
400	                  className="inline-block h-2 w-2 rounded-full bg-foreground"
401	                />
402	              ) : null}
403	            </AnimatePresence>
404	          </span>
405	        </span>
406	        {/* Status changes (Working… / failed / latest message) cross-fade. */}
407	        <AnimatePresence mode="wait" initial={false}>
408	          {preview ? (
409	            <m.span
410	              key={status}
411	              variants={fade}
412	              initial="hidden"
413	              animate="visible"
414	              exit="hidden"
415	              dir="auto"
416	              className={`truncate text-[12.5px] ${
417	                status !== "idle" || row?.unread ? "font-medium text-foreground/75" : "text-muted-foreground/70"
418	              }`}
419	            >
420	              {preview}
421	            </m.span>
422	          ) : null}
423	        </AnimatePresence>
424	      </Label>
425	    </m.button>
426	  );
427	}
428	
429	/** Compact rail: avatars only, featured agent first, then a divider and the specialists. */
430	export function RailPanel({ agents, rows, activeKey, onSelect, onNewChat, search, onToggleCompact }: SidebarPanelProps) {
431	  const stagger = useFirstLoadStagger();
432	  const { chrome } = useMorph();
433	  const { primary, specialists } = groupAgents(agents);
434	  const item = (agent: AgentSummary, index: number) => {
435	    const node = railItem(agent, index);
436	    // The rail lists every agent; ones hidden by the expanded panel's search have no
437	    // counterpart to fly to, so they fade like labels instead.
438	    return agentMatches(agent, search.query) ? (
439	      node
440	    ) : (
441	      <Label key={agent.key} className="flex">
442	        {node}
443	      </Label>
444	    );
445	  };
446	  const railItem = (agent: AgentSummary, index: number) => {
447	    const selected = agent.key === activeKey;
448	    const specialist = agent.key !== PRIMARY_AGENT_KEY;
449	    return (
450	      // Disabled mid-morph: closes an open tooltip and blocks new ones while avatars travel.
451	      <Tooltip key={agent.key} disabled={!chrome}>
452	        <TooltipTrigger
453	          render={
454	            <button
455	              type="button"
456	              data-testid="rail-agent"
457	              aria-label={agent.name}
458	              aria-current={selected ? "page" : undefined}
459	              onClick={() => onSelect(agent.key)}
460	              className="relative grid h-12 w-12 shrink-0 place-items-center rounded-[14px] transition-colors duration-(--motion-fast) ease-(--ease-standard) hover:bg-sidebar-accent/60"
461	            />
462	          }
463	        >
464	          {selected ? <SelectedHighlight radius={14} /> : null}
465	          <m.span
466	            className="relative z-[1] inline-flex"
467	            custom={index}
468	            variants={itemVariants}
469	            initial={stagger ? "hidden" : false}
470	            animate="visible"
471	          >
472	            {/* A specialist's unread badge counts as a label here: it fades out before the
473	                morph and the row's inline unread dot fades in after (and the reverse). */}
474	            <AgentAvatar agent={agent} size={40} row={rows[agent.key]} activityOnly={specialist && !chrome} />
475	          </m.span>
476	        </TooltipTrigger>
477	        <TooltipContent side="right" sideOffset={8}>
478	          {agent.name}
479	        </TooltipContent>
480	      </Tooltip>
481	    );
482	  };
483	
484	  // The rail layer spans the whole aside (inset-0) with a fixed 76px column, so while the
485	  // aside is still wider (collapsing) nothing in the rail clips an avatar travelling in.
486	  return (
487	    <div className="flex h-full min-h-0 flex-col">
488	      <Label className="flex h-[52px] w-[76px] shrink-0 items-center justify-center pt-2">
489	        {onToggleCompact ? (
490	          <button
491	            type="button"
492	            aria-label="Expand sidebar"
493	            title="Expand sidebar"
494	            onClick={onToggleCompact}
495	            className={iconButton}
496	          >
497	            <PanelLeftOpen size={16} strokeWidth={1.8} aria-hidden="true" />
498	          </button>
499	        ) : null}
500	      </Label>
501	      <nav aria-label="Agents" className="rk-scroll min-h-0 w-full flex-1 overflow-y-auto overflow-x-hidden py-1">
502	        <div className="flex w-[76px] flex-col items-center gap-1.5">
503	          {primary.map((agent, index) => item(agent, index))}
504	          {primary.length > 0 && specialists.length > 0 ? (
505	            <Label inline className="my-1 h-px w-8 shrink-0 bg-sidebar-border">
506	              {null}
507	            </Label>
508	          ) : null}
509	          {specialists.map((agent, index) => item(agent, index + primary.length))}
510	        </div>
511	      </nav>
512	      <Label className="flex w-[76px] shrink-0 flex-col items-center gap-1.5 pb-3 pt-2">
