// Minimal CDP driver for chrome-headless-shell using Node's global WebSocket.
import { spawn } from "node:child_process";
import { readdirSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";

const cache = `${homedir()}/Library/Caches/ms-playwright`;
const dir = readdirSync(cache).find((d) => d.startsWith("chromium_headless_shell-"));
const CHROME = `${cache}/${dir}/chrome-headless-shell-mac-arm64/chrome-headless-shell`;

export async function launch({ port = 9333, width = 1280, height = 800 } = {}) {
  const proc = spawn(CHROME, [
    `--remote-debugging-port=${port}`,
    `--window-size=${width},${height}`,
    "--no-first-run",
    "--user-data-dir=" + `/private/tmp/claude-501/-Users-apple-Open-nlhack/a4075510-47e1-4790-879c-d9950b6f901f/scratchpad/profile-${port}-${Date.now()}`,
    "about:blank",
  ], { stdio: "ignore" });
  let targets;
  for (let i = 0; i < 50; i++) {
    try {
      targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
      if (targets.some((t) => t.type === "page")) break;
    } catch {}
    await new Promise((r) => setTimeout(r, 100));
  }
  const page = targets.find((t) => t.type === "page");
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((r) => ws.addEventListener("open", r, { once: true }));
  let id = 0;
  const pending = new Map();
  ws.addEventListener("message", (e) => {
    const msg = JSON.parse(e.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result);
    }
  });
  const send = (method, params = {}) =>
    new Promise((resolve, reject) => {
      const n = ++id;
      pending.set(n, { resolve, reject });
      ws.send(JSON.stringify({ id: n, method, params }));
    });
  await send("Page.enable");
  await send("Runtime.enable");
  await send("Emulation.setDeviceMetricsOverride", { width, height, deviceScaleFactor: 1, mobile: false });
  const evaluate = async (expression) => {
    const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
    if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails).slice(0, 800));
    return r.result.value;
  };
  const screenshot = async (path) => {
    const r = await send("Page.captureScreenshot", { format: "png" });
    writeFileSync(path, Buffer.from(r.data, "base64"));
  };
  const close = () => {
    try { ws.close(); } catch {}
    proc.kill("SIGKILL");
  };
  return { send, evaluate, screenshot, close };
}

