// Injected into the page: rAF sampler for the sidebar morph.
window.__sampler = (() => {
  const aside = () => document.querySelector("[data-testid=sidebar]");
  const effOpacity = (el) => {
    let o = 1;
    for (let n = el; n && n !== document.body; n = n.parentElement) o *= parseFloat(getComputedStyle(n).opacity);
    return o;
  };
  const rectOf = (el) => {
    const r = el.getBoundingClientRect();
    return { x: +r.x.toFixed(1), y: +r.y.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1), o: +effOpacity(el).toFixed(3) };
  };
  const visible = (el) => {
    const r = el.getBoundingClientRect();
    return r.width > 0 && r.height > 0 && effOpacity(el) > 0.01;
  };
  const sample = () => {
    const a = aside();
    const f = { t: performance.now(), w: +a.getBoundingClientRect().width.toFixed(1), morph: a.dataset.morph, layout: a.dataset.layout };
    f.avatars = {};
    for (const el of document.querySelectorAll("[data-morph-avatar]")) {
      (f.avatars[el.dataset.morphAvatar] ??= []).push(rectOf(el));
    }
    f.highlight = [...document.querySelectorAll("[data-morph-highlight]")].map(rectOf);
    f.controls = {};
    for (const el of document.querySelectorAll("[data-morph-control]")) {
      (f.controls[el.dataset.morphControl] ??= []).push(rectOf(el));
    }
    let maxLabel = 0;
    for (const el of document.querySelectorAll("[data-morph-label]")) {
      if (el.getBoundingClientRect().width === 0) continue;
      maxLabel = Math.max(maxLabel, parseFloat(getComputedStyle(el).opacity));
    }
    f.label = +maxLabel.toFixed(3);
    return f;
  };
  let frames = [];
  let running = false;
  const loop = () => {
    if (!running) return;
    frames.push(sample());
    requestAnimationFrame(loop);
  };
  const handle = () => document.querySelector("[data-testid=sidebar-resize]");
  const enter = () => handle().dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true, cancelable: true }));
  return {
    sample,
    enter,
    start() { frames = []; running = true; requestAnimationFrame(loop); },
    stop() { running = false; return frames; },
    // Records while pressing Enter at the given offsets (ms), for `duration` ms.
    async run(offsets, duration) {
      this.start();
      const t0 = performance.now();
      for (const off of offsets) {
        const wait = t0 + off - performance.now();
        if (wait > 0) await new Promise((r) => setTimeout(r, wait));
        enter();
      }
      const rest = t0 + duration - performance.now();
      if (rest > 0) await new Promise((r) => setTimeout(r, rest));
      const out = this.stop();
      return { t0, frames: out };
    },
  };
})();

