import { readFileSync, writeFileSync } from "node:fs";
import { launch } from "./cdp.mjs";
const S = "/private/tmp/claude-501/-Users-apple-Open-nlhack/a4075510-47e1-4790-879c-d9950b6f901f/scratchpad";
const b = await launch({ port: 9341 });
try {
  await b.evaluate(`localStorage.clear(); location.href = "http://localhost:3921/"`);
  await new Promise((r) => setTimeout(r, 4000));
  await b.evaluate(readFileSync(`${S}/sampler.js`, "utf8"));
  const info = await b.evaluate(`(() => {
    const a = document.querySelector("[data-testid=sidebar]");
    return { layout: a?.dataset.layout, featured: document.querySelectorAll("[data-testid=featured-agent]").length,
      rows: document.querySelectorAll("[data-testid=specialist-row]").length,
      current: [...document.querySelectorAll("[aria-current=page]")].map(e => e.textContent.slice(0,30)) };
  })()`);
  console.log(info);
  const which = process.argv[2] || "assistant";
  if (which === "specialist") {
    await b.evaluate(`document.querySelectorAll("[data-testid=specialist-row]")[1].click()`);
    await new Promise((r) => setTimeout(r, 800));
  }
  const col = await b.evaluate(`__sampler.run([0], 1100)`);
  const exp = await b.evaluate(`__sampler.run([0], 1100)`);
  writeFileSync(`${S}/probe-${which}.json`, JSON.stringify({ col, exp }));
  for (const [name, run] of [["collapse", col], ["expand", exp]]) {
    console.log("==", name);
    let prev;
    for (const f of run.frames) {
      const h = f.highlight.map((r) => `${r.x},${r.y} ${r.w}x${r.h} o${r.o}`).join(" | ");
      const line = `${(f.t - run.t0).toFixed(0).padStart(5)} w${f.w} ${f.morph} ${f.layout} L${f.label} H[${f.highlight.length}] ${h}`;
      if (line.slice(6) !== prev) console.log(line);
      prev = line.slice(6);
    }
  }
} finally {
  b.close();
}

