import { readFileSync, writeFileSync } from "node:fs";
import { launch } from "./cdp.mjs";
const S = "/private/tmp/claude-501/-Users-apple-Open-nlhack/a4075510-47e1-4790-879c-d9950b6f901f/scratchpad";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const results = [];
const check = (name, ok, detail = "") => {
  results.push({ name, ok, detail });
  console.log(`${ok ? "PASS" : "FAIL"} ${name}${detail ? " — " + detail : ""}`);
};

async function open(b, { reduce = false, theme } = {}) {
  if (reduce) await b.send("Emulation.setEmulatedMedia", { features: [{ name: "prefers-reduced-motion", value: "reduce" }] });
  await b.send("Page.navigate", { url: "http://localhost:3921/" });
  await sleep(3500);
  if (theme) {
    const cur = await b.evaluate(`document.documentElement.dataset.theme`);
    if (cur !== theme) {
      await b.evaluate(`document.querySelector("[data-morph-control=theme]").closest("button").click()`);
      await sleep(400);
    }
  }
  await b.evaluate(readFileSync(`${S}/sampler.js`, "utf8"));
}

/** Shared elements: avatars per key, highlight, controls. Returns {name: rect|null|"dup"} of visible copies. */
function shared(f) {
  const out = {};
  const pick = (name, list) => {
    const vis = (list ?? []).filter((r) => r.w > 0 && r.o > 0.01);
    out[name] = vis.length === 1 ? vis[0] : vis.length === 0 ? null : "dup";
  };
  for (const [k, list] of Object.entries(f.avatars)) pick(`avatar:${k}`, list);
  pick("highlight", f.highlight);
  for (const c of ["toggle", "new-chat", "theme"]) pick(c, f.controls[c]);
  return out;
}
const centre = (r) => [r.x + r.w / 2, r.y + r.h / 2];

function analyse(name, run, { expectMoves = true } = {}) {
  const fr = run.frames;
  let missing = 0, dups = 0, maxJump = 0, jumpAt = "", labelWhileMoving = 0;
  let prev = null;
  for (const f of fr) {
    const s = shared(f);
    let moving = false;
    for (const [k, r] of Object.entries(s)) {
      if (r === null) { missing++; continue; }
      if (r === "dup") { dups++; continue; }
      const p = prev?.[k];
      if (p && typeof p === "object") {
        const [x0, y0] = centre(p), [x1, y1] = centre(r);
        const d = Math.hypot(x1 - x0, y1 - y0) + Math.abs(r.w - p.w) + Math.abs(r.h - p.h);
        if (d > 0.3) moving = true;
        if (d > maxJump) { maxJump = d; jumpAt = `${k}@${(f.t - run.t0).toFixed(0)}ms`; }
      }
    }
    if (prev && prev.__w !== f.w) moving = true;
    if (moving && f.label > 0.01) labelWhileMoving++;
    prev = { ...s, __w: f.w };
  }
  check(`${name}: one visible copy of each shared element`, missing === 0 && dups === 0, `missing=${missing} dup=${dups}`);
  check(`${name}: no jump >40px`, maxJump <= 40, `max=${maxJump.toFixed(1)}px (${jumpAt})`);
  check(`${name}: labels at 0 while travelling`, labelWhileMoving === 0, `frames with label>0 while moving=${labelWhileMoving}`);
  return { maxJump };
}

/** Normalised progress samples: at τ in [0,1] across the travel window, rects of all shared elements. */
function travelWindow(run) {
  const fr = run.frames;
  const w0 = fr[0].w, w1 = fr.at(-1).w;
  const startIdx = fr.findIndex((f) => f.w !== w0);
  let endIdx = fr.findIndex((f, i) => i > startIdx && f.w === w1);
  return { start: fr[startIdx - 1], end: fr[endIdx], frames: fr.slice(startIdx - 1, endIdx + 1) };
}
function stateAtWidth(frames, w) {
  // interpolate shared rects at a given aside width (width is monotonic in a single toggle)
  for (let i = 1; i < frames.length; i++) {
    const a = frames[i - 1], b = frames[i];
    if ((a.w - w) * (b.w - w) <= 0 && a.w !== b.w) {
      const k = (w - a.w) / (b.w - a.w);
      const sa = shared(a), sb = shared(b), out = {};
      for (const key of Object.keys(sa)) {
        const ra = sa[key], rb = sb[key];
        if (!ra || !rb || ra === "dup" || rb === "dup") continue;
        out[key] = { x: ra.x + (rb.x - ra.x) * k, y: ra.y + (rb.y - ra.y) * k, w: ra.w + (rb.w - ra.w) * k, h: ra.h + (rb.h - ra.h) * k };
      }
      return out;
    }
  }
  return null;
}
function symmetry(col, exp) {
  // compare geometry at equal aside widths (collapse(1-τ) and expand(τ) share width if symmetric),
  // plus time symmetry of the width curve
  const c = travelWindow(col), e = travelWindow(exp);
  let worst = 0, at = "";
  for (let w = 90; w <= 270; w += 15) {
    const sc = stateAtWidth(c.frames, w), se = stateAtWidth(e.frames, w);
    if (!sc || !se) continue;
    for (const k of Object.keys(sc)) {
      if (!se[k]) continue;
      const d = Math.max(Math.abs(sc[k].x - se[k].x), Math.abs(sc[k].y - se[k].y), Math.abs(sc[k].w - se[k].w), Math.abs(sc[k].h - se[k].h));
      if (d > worst) { worst = d; at = `${k}@w${w}`; }
    }
  }
  // width over time: expand(τ) vs collapse(1-τ)
  const dur = (win) => win.end.t - win.start.t;
  const dc = dur(c), de = dur(e);
  let wworst = 0;
  for (let tau = 0.1; tau <= 0.9; tau += 0.1) {
    const we = widthAt(e.frames, e.start.t + tau * de);
    const wc = widthAt(c.frames, c.start.t + (1 - tau) * dc);
    wworst = Math.max(wworst, Math.abs(we - wc));
  }
  return { worst, at, wworst, dc, de };
}
function widthAt(frames, t) {
  for (let i = 1; i < frames.length; i++) {
    if (frames[i].t >= t) {
      const a = frames[i - 1], b = frames[i];
      return a.w + ((b.w - a.w) * (t - a.t)) / (b.t - a.t);
    }
  }
  return frames.at(-1).w;
}
function timeline(run) {
  const fr = run.frames;
  const rel = (f) => (f ? (f.t - run.t0).toFixed(0) : "-");
  const firstLabel0 = fr.find((f) => f.label < 0.01);
  const w0 = fr[0].w;
  const moveStart = fr.find((f) => f.w !== w0);
  const w1 = fr.at(-1).w;
  const moveEnd = fr.find((f, i) => fr.indexOf(moveStart) < i && f.w === w1);
  const labelBack = fr.find((f) => f.t > (moveEnd?.t ?? 0) && f.label > 0.99);
  return `labels→0 @${rel(firstLabel0)} · travel ${rel(moveStart)}–${rel(moveEnd)} · labels→1 @${rel(labelBack)}`;
}

const b = await launch({ port: 9351 });
try {
  // 1. Assistant selected: collapse + expand
  await open(b);
  const col = await b.evaluate(`__sampler.run([0], 1300)`);
  await sleep(200);
  const exp = await b.evaluate(`__sampler.run([0], 1300)`);
  writeFileSync(`${S}/run-assistant.json`, JSON.stringify({ col, exp }));
  console.log("collapse:", timeline(col));
  console.log("expand:  ", timeline(exp));
  analyse("collapse (assistant)", col);
  analyse("expand (assistant)", exp);
  const sym = symmetry(col, exp);
  check("symmetry: shared geometry at equal width", sym.worst <= 2, `max Δ=${sym.worst.toFixed(2)}px (${sym.at})`);
  check("symmetry: width expand(τ) ≈ collapse(1−τ)", sym.wworst <= 2, `max Δ=${sym.wworst.toFixed(2)}px, travel ${sym.dc.toFixed(0)}/${sym.de.toFixed(0)}ms`);

  // 2. Specialist selected
  await b.evaluate(`document.querySelectorAll("[data-testid=specialist-row]")[1].click()`);
  await sleep(700);
  const col2 = await b.evaluate(`__sampler.run([0], 1300)`);
  await sleep(200);
  const exp2 = await b.evaluate(`__sampler.run([0], 1300)`);
  analyse("collapse (specialist)", col2);
  analyse("expand (specialist)", exp2);
  const sym2 = symmetry(col2, exp2);
  check("symmetry (specialist)", sym2.worst <= 2 && sym2.wworst <= 2, `geom Δ=${sym2.worst.toFixed(2)} width Δ=${sym2.wworst.toFixed(2)}`);

  // 3. Rapid toggles
  for (const offsets of [[0, 80], [0, 230], [0, 300], [0, 520], [0, 560], [0, 80, 230, 300, 520, 560]]) {
    const before = await b.evaluate(`document.querySelector("[data-testid=sidebar]").dataset.layout`);
    const run = await b.evaluate(`__sampler.run(${JSON.stringify(offsets)}, ${Math.max(...offsets) + 1500})`);
    const last = run.frames.at(-1);
    const expected = offsets.length % 2 === 0 ? before : before === "rail" ? "expanded" : "rail";
    const expW = expected === "rail" ? 76 : 284;
    const s = analyse(`rapid ${offsets.join("/")}`, run);
    check(`rapid ${offsets.join("/")}: settles`, last.layout === expected && last.morph === "idle" && Math.abs(last.w - expW) < 0.5 && last.label > 0.99,
      `layout=${last.layout} w=${last.w} morph=${last.morph} label=${last.label}`);
  }

  // 4. Drag snap to rail and back with pointer held
  const st = await b.evaluate(`document.querySelector("[data-testid=sidebar]").dataset.layout`);
  if (st !== "expanded") { await b.evaluate(`__sampler.enter()`); await sleep(1200); }
  const h = await b.evaluate(`(() => { const r = document.querySelector("[data-testid=sidebar-resize]").getBoundingClientRect(); return { x: r.x + r.width / 2, y: r.y + 300 }; })()`);
  await b.evaluate(`__sampler.start()`);
  const mouse = (type, x) => b.send("Input.dispatchMouseEvent", { type, x, y: h.y, button: "left", buttons: type === "mouseReleased" ? 0 : 1, clickCount: 1 });
  await mouse("mousePressed", h.x);
  for (let x = h.x; x >= 30; x -= 12) { await mouse("mouseMoved", x); await sleep(16); }
  await sleep(900);
  const mid = await b.evaluate(`__sampler.sample()`);
  for (let x = 30; x <= 330; x += 12) { await mouse("mouseMoved", x); await sleep(16); }
  await sleep(900);
  const held = await b.evaluate(`__sampler.sample()`);
  await mouse("mouseReleased", 330);
  await sleep(300);
  const dragFrames = await b.evaluate(`__sampler.stop()`);
  analyse("drag snap", { t0: dragFrames[0].t, frames: dragFrames });
  check("drag: snapped to rail with labels visible (pointer held)", mid.layout === "rail" && mid.morph === "idle" && mid.label > 0.99, `layout=${mid.layout} label=${mid.label}`);
  check("drag: snapped back to expanded with labels visible (pointer held)", held.layout === "expanded" && held.morph === "idle" && held.label > 0.99, `layout=${held.layout} w=${held.w} label=${held.label}`);

  // 5. Mid-transition screenshots (dark + light)
  for (const theme of ["dark", "light"]) {
    await open(b, { theme });
    for (const [dir, at] of [["collapse", 420], ["expand", 420]]) {
      await b.evaluate(`__sampler.enter()`);
      await sleep(at);
      await b.screenshot(`${S}/mid-${dir}-${theme}.png`);
      await sleep(1100);
    }
  }
} finally {
  b.close();
}

// 6. Reduced motion
const r = await launch({ port: 9352 });
try {
  await open(r, { reduce: true });
  const run = await r.evaluate(`__sampler.run([0], 400)`);
  const changed = run.frames.findIndex((f) => f.layout === "rail");
  const f = run.frames[changed];
  const intermediates = run.frames.filter((x) => x.w !== 284 && x.w !== 76).length;
  const labelDips = run.frames.filter((x) => x.label < 0.99).length;
  check("reduced motion: instant", changed >= 0 && f.w === 76 && intermediates === 0 && labelDips === 0, `frame ${changed} w=${f?.w} intermediates=${intermediates} labelDips=${labelDips}`);
  analyse("reduced motion", run);
} finally {
  r.close();
}
const failed = results.filter((x) => !x.ok);
console.log(`\n${results.length - failed.length}/${results.length} passed`);
writeFileSync(`${S}/verify-results.json`, JSON.stringify(results, null, 1));

